//! Code generator: produces `gen_tablegen.rs` from build-time extraction output.
//!
//! The generated file defines `load_from_generated() -> TblgenOutput` which
//! constructs the same data structure as the former `load_full_via_tblgen()`,
//! but from compiled-in constants instead of runtime LLVM linkage.

use std::fmt::Write;
use std::path::Path;

use super::extract::*;
use super::records::BuildInstrEncoding;

/// Generate per-slot `gen_tblgen_slot_*.rs` files and a root `gen_tablegen.rs`
/// in `$OUT_DIR`.
///
/// Splitting encodings into per-slot files lets rustc compile them in parallel
/// instead of churning through one 39K-line monolith.
pub fn generate_tablegen_file(output: &BuildTblgenOutput, out_dir: &Path) {
    let mut slot_names: Vec<&String> = output.encodings_by_slot.keys().collect();
    slot_names.sort();

    // Emit one file per slot containing a function that returns Vec<InstrEncoding>.
    for slot in &slot_names {
        let encodings = &output.encodings_by_slot[*slot];
        let mut code = String::with_capacity(256 * 1024);
        writeln!(code, "// Auto-generated by build.rs -- do not edit.").unwrap();
        writeln!(code, "use super::super::types::*;").unwrap();
        writeln!(code, "use super::super::resolver::*;").unwrap();
        writeln!(code).unwrap();
        writeln!(code, "pub(crate) fn encodings() -> Vec<InstrEncoding> {{").unwrap();
        writeln!(code, "    vec![").unwrap();
        for enc in encodings {
            format_encoding(&mut code, enc);
        }
        writeln!(code, "    ]").unwrap();
        writeln!(code, "}}").unwrap();

        let filename = format!("gen_tblgen_slot_{}.rs", slot);
        std::fs::write(out_dir.join(&filename), &code).unwrap();
    }

    // Emit the root file that assembles everything.
    let mut code = String::with_capacity(64 * 1024);
    writeln!(code, "// Auto-generated by build.rs -- do not edit.").unwrap();
    writeln!(code, "// Source: llvm-aie TableGen extraction at build time.").unwrap();
    writeln!(code).unwrap();

    // Declare per-slot submodules.
    for slot in &slot_names {
        writeln!(
            code,
            "mod slot_{} {{ include!(concat!(env!(\"OUT_DIR\"), \"/gen_tblgen_slot_{}.rs\")); }}",
            slot, slot
        )
        .unwrap();
    }
    writeln!(code).unwrap();

    writeln!(code, "/// Load instruction decoder data from build-time extracted constants.").unwrap();
    writeln!(code, "pub(crate) fn load_from_generated() -> super::types::TblgenOutput {{").unwrap();
    writeln!(code, "    use super::types::*;").unwrap();
    writeln!(code, "    use super::resolver::*;").unwrap();
    writeln!(code, "    use std::collections::HashMap;").unwrap();
    writeln!(code).unwrap();

    // Collect per-slot encodings.
    writeln!(code, "    let mut encodings_by_slot: HashMap<String, Vec<InstrEncoding>> = HashMap::new();")
        .unwrap();
    for slot in &slot_names {
        writeln!(code, "    encodings_by_slot.insert({:?}.to_string(), slot_{}::encodings());", slot, slot)
            .unwrap();
    }

    // Processor model
    writeln!(code).unwrap();
    if let Some(ref model) = output.processor_model {
        writeln!(code, "    let processor_model = Some(ProcessorModel {{").unwrap();
        writeln!(code, "        load_latency: {},", model.load_latency).unwrap();
        writeln!(code, "        high_latency: {},", model.high_latency).unwrap();
        writeln!(code, "        mispredict_penalty: {},", model.mispredict_penalty).unwrap();
        writeln!(code, "        issue_width: {},", model.issue_width).unwrap();
        writeln!(code, "        itinerary_name: {:?}.to_string(),", model.itinerary_name).unwrap();
        writeln!(code, "    }});").unwrap();
    } else {
        writeln!(code, "    let processor_model: Option<ProcessorModel> = None;").unwrap();
    }

    // Itineraries
    writeln!(code).unwrap();
    writeln!(code, "    let mut itineraries: HashMap<String, ItineraryInfo> = HashMap::new();").unwrap();
    let mut itin_names: Vec<&String> = output.itineraries.keys().collect();
    itin_names.sort();
    for name in &itin_names {
        let info = &output.itineraries[*name];
        format_itinerary(&mut code, info);
    }

    // Register model
    writeln!(code).unwrap();
    writeln!(code, "    let mut reg_registers: HashMap<String, RegisterDef> = HashMap::new();").unwrap();
    let mut reg_names: Vec<&String> = output.register_model.registers.keys().collect();
    reg_names.sort();
    for name in &reg_names {
        let reg = &output.register_model.registers[*name];
        writeln!(code, "    reg_registers.insert({:?}.to_string(), RegisterDef {{", name).unwrap();
        writeln!(code, "        name: {:?}.to_string(),", reg.name).unwrap();
        writeln!(code, "        hw_encoding: {},", reg.hw_encoding).unwrap();
        writeln!(
            code,
            "        parents: vec![{}],",
            reg.parents
                .iter()
                .map(|p| format!("{:?}.to_string()", p))
                .collect::<Vec<_>>()
                .join(", ")
        )
        .unwrap();
        writeln!(code, "    }});").unwrap();
    }

    writeln!(code).unwrap();
    writeln!(code, "    let mut reg_classes: HashMap<String, RegisterClassDef> = HashMap::new();").unwrap();
    let mut class_names: Vec<&String> = output.register_model.classes.keys().collect();
    class_names.sort();
    for name in &class_names {
        let cls = &output.register_model.classes[*name];
        writeln!(code, "    reg_classes.insert({:?}.to_string(), RegisterClassDef {{", name).unwrap();
        writeln!(code, "        name: {:?}.to_string(),", cls.name).unwrap();
        writeln!(
            code,
            "        members: vec![{}],",
            cls.members
                .iter()
                .map(|m| format!("{:?}.to_string()", m))
                .collect::<Vec<_>>()
                .join(", ")
        )
        .unwrap();
        writeln!(code, "        alignment: {},", cls.alignment).unwrap();
        writeln!(
            code,
            "        parents: vec![{}],",
            cls.parents
                .iter()
                .map(|p| format!("{:?}.to_string()", p))
                .collect::<Vec<_>>()
                .join(", ")
        )
        .unwrap();
        writeln!(code, "    }});").unwrap();
    }

    writeln!(code).unwrap();
    writeln!(
        code,
        "    let register_model = RegisterModel {{ registers: reg_registers, classes: reg_classes }};"
    )
    .unwrap();

    // Composite formats
    writeln!(code).unwrap();
    writeln!(code, "    let composite_formats = vec![").unwrap();
    for fmt in &output.composite_formats {
        format_composite(&mut code, fmt);
    }
    writeln!(code, "    ];").unwrap();

    // Return
    writeln!(code).unwrap();
    writeln!(code, "    TblgenOutput {{").unwrap();
    writeln!(code, "        encodings_by_slot,").unwrap();
    writeln!(code, "        processor_model,").unwrap();
    writeln!(code, "        itineraries,").unwrap();
    writeln!(code, "        register_model,").unwrap();
    writeln!(code, "        composite_formats,").unwrap();
    writeln!(code, "    }}").unwrap();
    writeln!(code, "}}").unwrap();

    std::fs::write(out_dir.join("gen_tablegen.rs"), &code).unwrap();

    let total: usize = slot_names
        .iter()
        .map(|s| {
            let p = out_dir.join(format!("gen_tblgen_slot_{}.rs", s));
            std::fs::metadata(&p).map(|m| m.len() as usize).unwrap_or(0)
        })
        .sum::<usize>()
        + code.len();
    eprintln!("cargo:warning=Generated {} slot files + root ({} bytes total)", slot_names.len(), total);
}

// ---------------------------------------------------------------------------
// Formatting helpers
// ---------------------------------------------------------------------------

fn format_encoding(code: &mut String, enc: &BuildInstrEncoding) {
    writeln!(code, "        InstrEncoding {{").unwrap();
    writeln!(code, "            name: {:?}.to_string(),", enc.name).unwrap();
    writeln!(code, "            mnemonic: {:?}.to_string(),", enc.mnemonic).unwrap();
    writeln!(code, "            asm_string: {:?}.to_string(),", enc.asm_string).unwrap();
    writeln!(code, "            slot: {:?}.to_string(),", enc.slot).unwrap();
    writeln!(code, "            width: {},", enc.width).unwrap();
    writeln!(code, "            fixed_mask: 0x{:X},", enc.fixed_mask).unwrap();
    writeln!(code, "            fixed_bits: 0x{:X},", enc.fixed_bits).unwrap();

    // Operand fields
    writeln!(code, "            operand_fields: vec![").unwrap();
    for field in &enc.operand_fields {
        format_operand_field(code, field);
    }
    writeln!(code, "            ],").unwrap();

    // Semantic
    match &enc.semantic {
        Some(s) => writeln!(code, "            semantic: Some({}),", s).unwrap(),
        None => writeln!(code, "            semantic: None,").unwrap(),
    }

    writeln!(code, "            may_load: {},", enc.may_load).unwrap();
    writeln!(code, "            may_store: {},", enc.may_store).unwrap();

    // Input/output order
    writeln!(
        code,
        "            input_order: vec![{}],",
        enc.input_order
            .iter()
            .map(|n| format!("{:?}.to_string()", n))
            .collect::<Vec<_>>()
            .join(", ")
    )
    .unwrap();
    writeln!(
        code,
        "            output_order: vec![{}],",
        enc.output_order
            .iter()
            .map(|n| format!("{:?}.to_string()", n))
            .collect::<Vec<_>>()
            .join(", ")
    )
    .unwrap();

    // Implicit regs
    writeln!(code, "            implicit_regs: vec![").unwrap();
    for reg in &enc.implicit_regs {
        writeln!(
            code,
            "                ImplicitReg {{ reg_class: {:?}.to_string(), reg_num: {}, is_use: {} }},",
            reg.reg_class, reg.reg_num, reg.is_use
        )
        .unwrap();
    }
    writeln!(code, "            ],").unwrap();

    writeln!(code, "            addressing_mode: {},", enc.addressing_mode).unwrap();
    writeln!(code, "            mem_width: {},", enc.mem_width).unwrap();
    writeln!(code, "            has_complete_decoder: {},", enc.has_complete_decoder).unwrap();

    match &enc.element_type {
        Some(s) => writeln!(code, "            element_type: Some({}),", s).unwrap(),
        None => writeln!(code, "            element_type: None,").unwrap(),
    }
    match &enc.from_type {
        Some(s) => writeln!(code, "            from_type: Some({}),", s).unwrap(),
        None => writeln!(code, "            from_type: None,").unwrap(),
    }
    match &enc.branch_condition {
        Some(s) => writeln!(code, "            branch_condition: Some({}),", s).unwrap(),
        None => writeln!(code, "            branch_condition: None,").unwrap(),
    }
    writeln!(code, "            is_vector: {},", enc.is_vector).unwrap();
    match &enc.select_variant {
        Some(s) => writeln!(code, "            select_variant: Some({}),", s).unwrap(),
        None => writeln!(code, "            select_variant: None,").unwrap(),
    }
    writeln!(code, "            is_ptr_arithmetic: {},", enc.is_ptr_arithmetic).unwrap();
    writeln!(code, "            is_sp_relative: {},", enc.is_sp_relative).unwrap();
    match &enc.sched_class {
        Some(s) => writeln!(code, "            sched_class: Some({:?}.to_string()),", s).unwrap(),
        None => writeln!(code, "            sched_class: None,").unwrap(),
    }
    writeln!(code, "        }},").unwrap();
}

fn format_operand_field(code: &mut String, field: &super::records::BuildOperandField) {
    writeln!(code, "                {{").unwrap();
    writeln!(
        code,
        "                    let mut f = OperandField::new({:?}, {}, {});",
        field.name, field.bit_position, field.width
    )
    .unwrap();
    writeln!(code, "                    f.signed = {};", field.signed).unwrap();
    writeln!(code, "                    f.operand_type = {};", field.operand_type).unwrap();
    writeln!(code, "                    f.is_output = {};", field.is_output).unwrap();
    if !field.fragments.is_empty() {
        writeln!(code, "                    f.fragments = vec![").unwrap();
        for frag in &field.fragments {
            writeln!(
                code,
                "                        FieldFragment {{ inst_bit: {}, width: {}, target_bit: {} }},",
                frag.inst_bit, frag.width, frag.target_bit
            )
            .unwrap();
        }
        writeln!(code, "                    ];").unwrap();
    }
    writeln!(code, "                    f").unwrap();
    writeln!(code, "                }},").unwrap();
}

fn format_itinerary(code: &mut String, info: &BuildItineraryInfo) {
    writeln!(code, "    itineraries.insert({:?}.to_string(), ItineraryInfo {{", info.class_name).unwrap();
    writeln!(code, "        class_name: {:?}.to_string(),", info.class_name).unwrap();
    writeln!(code, "        total_latency: {},", info.total_latency).unwrap();
    writeln!(
        code,
        "        operand_cycles: vec![{}],",
        info.operand_cycles.iter().map(|c| c.to_string()).collect::<Vec<_>>().join(", ")
    )
    .unwrap();
    writeln!(code, "        stages: vec![").unwrap();
    for stage in &info.stages {
        writeln!(
            code,
            "            PipelineStage {{ cycles: {}, units: vec![{}], time_inc: {} }},",
            stage.cycles,
            stage
                .units
                .iter()
                .map(|u| format!("{:?}.to_string()", u))
                .collect::<Vec<_>>()
                .join(", "),
            stage.time_inc
        )
        .unwrap();
    }
    writeln!(code, "        ],").unwrap();
    writeln!(
        code,
        "        bypasses: vec![{}],",
        info.bypasses
            .iter()
            .map(|b| format!("{:?}.to_string()", b))
            .collect::<Vec<_>>()
            .join(", ")
    )
    .unwrap();
    writeln!(code, "    }});").unwrap();
}

fn format_composite(code: &mut String, fmt: &BuildCompositeFormat) {
    writeln!(code, "        CompositeFormatDef {{").unwrap();
    writeln!(code, "            name: {:?}.to_string(),", fmt.name).unwrap();
    writeln!(code, "            total_bytes: {},", fmt.total_bytes).unwrap();
    writeln!(code, "            total_bits: {},", fmt.total_bits).unwrap();
    writeln!(
        code,
        "            slots: vec![{}],",
        fmt.slots
            .iter()
            .map(|(n, w)| format!("({:?}.to_string(), {})", n, w))
            .collect::<Vec<_>>()
            .join(", ")
    )
    .unwrap();
    writeln!(code, "            fixed_mask: 0x{:X},", fmt.fixed_mask).unwrap();
    writeln!(code, "            fixed_value: 0x{:X},", fmt.fixed_value).unwrap();
    writeln!(code, "            slot_maps: vec![").unwrap();
    for sm in &fmt.slot_maps {
        writeln!(
            code,
            "                SlotBitMap {{ slot_name: {:?}.to_string(), width: {}, start_bit: {} }},",
            sm.slot_name, sm.width, sm.start_bit
        )
        .unwrap();
    }
    writeln!(code, "            ],").unwrap();
    writeln!(code, "        }},").unwrap();
}

/// Generate `gen_unpack_forms.rs`: the `UNPACK_FORMS` table and the by-mnemonic lookup,
/// included by `aie2::unpack`.
///
/// One entry per mnemonic. The index and post-modify records of a fused load share a
/// mnemonic (the decoder tells them apart by operands) and must agree on everything this
/// table carries; the build fails if they do not. Widths come from the mnemonic
/// (`...s16.s8`: 16-bit lanes out of 8-bit lanes) and are cross-checked against the `sz`
/// encoding bit, and the sign letter against `sgn`, so a TableGen change that breaks the
/// relationship fails the build.
pub fn generate_unpack_forms(forms: &[super::records::BuildUnpackForm], out_dir: &Path) {
    use std::collections::BTreeMap;

    let mut by_mnemonic: BTreeMap<&str, (String, &super::records::BuildUnpackForm)> = BTreeMap::new();
    for f in forms {
        let widths: Vec<u8> = f
            .mnemonic
            .rsplit('.')
            .take(2)
            .map(|t| {
                t[1..]
                    .parse::<u8>()
                    .unwrap_or_else(|_| panic!("{}: unparsable width in {}", f.record, f.mnemonic))
            })
            .collect();
        let (bits_in, bits_out) = (widths[0], widths[1]);
        assert_eq!(f.sz, u8::from(bits_in == 8), "{}: sz bit disagrees with {}", f.record, f.mnemonic);
        let signed_mnemonic = f.mnemonic.rsplit('.').nth(1).is_some_and(|t| t.starts_with('s'));
        assert_eq!(f.sgn == 1, signed_mnemonic, "{}: sgn bit disagrees with {}", f.record, f.mnemonic);
        assert!(f.sign_register.is_none() || f.sgn == 0, "{}: sign register on a sgn=1 form", f.record);
        let sign = match &f.sign_register {
            Some((name, id)) => format!("UnpackSign::Register {{ name: \"{name}\", id: {id} }}"),
            None => format!("UnpackSign::Fixed({})", f.sgn == 1),
        };
        let addressing = match f.addressing.as_str() {
            "" => "UnpackAddressing::Register",
            "idx" | "pstm" => "UnpackAddressing::Linear",
            "2d" => "UnpackAddressing::TwoDim",
            "3d" => "UnpackAddressing::ThreeDim",
            other => panic!("{}: addressing {other}", f.record),
        };
        let kind = if f.fused {
            "UnpackKind::FusedLoad"
        } else {
            "UnpackKind::Standalone"
        };
        let entry = format!(
            "UnpackForm {{ mnemonic: \"{}\", kind: {kind}, addressing: {addressing}, \
             bits_in: {bits_in}, bits_out: {bits_out}, sign: {sign} }}",
            f.mnemonic
        );
        match by_mnemonic.get(f.mnemonic.as_str()) {
            Some((existing, first)) => assert_eq!(
                existing, &entry,
                "{} and {} share the mnemonic {} but differ",
                first.record, f.record, f.mnemonic
            ),
            None => {
                by_mnemonic.insert(f.mnemonic.as_str(), (entry, f));
            }
        }
    }

    let mut code = String::new();
    writeln!(code, "// Auto-generated by build.rs -- do not edit.").unwrap();
    writeln!(code, "// Source: llvm-aie TableGen unpack instruction records.").unwrap();
    writeln!(code).unwrap();
    writeln!(code, "pub const UNPACK_FORMS: &[UnpackForm] = &[").unwrap();
    for (entry, _) in by_mnemonic.values() {
        writeln!(code, "    {entry},").unwrap();
    }
    writeln!(code, "];").unwrap();
    writeln!(code).unwrap();
    writeln!(code, "/// The unpack form of an assembly mnemonic, if it is one.").unwrap();
    writeln!(code, "pub fn unpack_form(mnemonic: &str) -> Option<&'static UnpackForm> {{").unwrap();
    writeln!(code, "    match mnemonic {{").unwrap();
    for (i, mnemonic) in by_mnemonic.keys().enumerate() {
        writeln!(code, "        \"{mnemonic}\" => Some(&UNPACK_FORMS[{i}]),").unwrap();
    }
    writeln!(code, "        _ => None,").unwrap();
    writeln!(code, "    }}").unwrap();
    writeln!(code, "}}").unwrap();
    std::fs::write(out_dir.join("gen_unpack_forms.rs"), code).unwrap();
}
